<?php $saved=false;if($_SERVER['REQUEST_METHOD']==='POST'){ $saved=true;}?><section><div class="page-heading"><div><span class="eyebrow">CHW reporting</span><h2>Create Monthly Report</h2><p>HTML5 validation is used for the PHP frontend form.</p></div><a class="secondary" href="?page=reports">← Back</a></div><form class="panel" id="reportForm" method="post"><div class="notice compact"><span>i</span><p>Prototype only. Validation happens in the browser and no health data is persisted.</p></div><div class="form-grid"><?php $fields=[['period','Report period','month'],['households_visited','Households visited','number'],['household_followups','Household follow-ups','number'],['health_education_sessions','Health education sessions','number'],['referrals','Referrals','number'],['referral_followups','Referral follow-ups','number'],['maternal_activities','Maternal-health activities','number'],['child_activities','Child-health activities','number'],['community_events','Community events','number'],['other_activities','Other activities','number']];foreach($fields as [$k,$l,$t]):?><label><?=htmlspecialchars($l)?><input name="<?=htmlspecialchars($k)?>" type="<?=$t?>" value="<?=htmlspecialchars($_POST[$k]??($t==='month'?'2026-09':''))?>" required <?=$t==='number'?'min="0" max="9999" step="1"':''?>></label><?php endforeach;?></div><div class="modal-actions"><a class="secondary" href="?page=reports">Cancel</a><button class="primary">Save draft</button></div><?php if($saved):?><div class="notice compact"><span>✓</span><p>HTML5 validation passed. Prototype draft prepared; future backend persistence will use a secured API.</p></div><?php endif;?></form></section>
